def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Join aligned pairs of 1s with a diagonal segment.
    directions = set()
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr and abs(dr) == abs(dc):
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                directions.add((sr, sc))
                for k in range(abs(dr) + 1):
                    r, c = r1 + k * sr, c1 + k * sc
                    if grid[r][c] != 6:
                        out[r][c] = 1

    # A 6 on a 1-defined diagonal draws a full diagonal in the perpendicular
    # diagonal direction.
    for sr, sc in directions:
        for r, c in sixes:
            if any((r - a) * sc == (c - b) * sr
                   for a, b in ones):
                pr, pc = -sr, sc
                rr, cc = r, c
                while 0 <= rr - pr < h and 0 <= cc - pc < w:
                    rr -= pr
                    cc -= pc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != 1:
                        out[rr][cc] = 6
                    rr += pr
                    cc += pc
    return out
